// 1) Auth simple par en-tête partagé avec la GitHub Action.
const secret = $env.N8N_WEBHOOK_SECRET;
const got = $json.headers?.['x-webhook-secret'];
if (secret && got !== secret) {
  throw new Error('Unauthorized: x-webhook-secret invalide');
}

// La payload utile est dans body (webhook n8n).
const body = $json.body ?? $json;
const { slug, lang = 'fr', path = '', commit = '', raw = '' } = body;

if (!slug) throw new Error('slug manquant');
if (!raw) throw new Error('raw (contenu MDX) manquant');

// 2) Parse minimal du frontmatter YAML (entre les deux premiers ---).
//    On n'a besoin que de title / excerpt / image ; on ignore tags/faq.
function parseFrontmatter(src) {
  const m = src.match(/^---\n([\s\S]*?)\n---/);
  const fm = {};
  let bodyMd = src;
  if (m) {
    bodyMd = src.slice(m[0].length);
    for (const line of m[1].split('\n')) {
      const kv = line.match(/^([A-Za-z0-9_]+):\s*(.*)$/);
      if (!kv) continue;
      let [, k, v] = kv;
      v = v.trim().replace(/^["']|["']$/g, '');
      if (v !== '') fm[k] = v;
    }
  }
  return { fm, bodyMd };
}

const { fm, bodyMd } = parseFrontmatter(raw);
const title = fm.title || slug;
const excerpt = fm.excerpt || '';
const image = fm.image || `/assets/blog/${slug}.webp`;
const seoTitle = fm.seoTitle || '';

if (!title) throw new Error('title manquant dans le frontmatter');
if (!bodyMd.trim()) throw new Error('corps MDX vide');

// 3) Nettoyage du corps : retire JSX/HTML, compacte, tronque.
const content = bodyMd
  .replace(/import\s+.*?from\s+['"].*?['"];?/g, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\n{2,}/g, '\n')
  .trim()
  .substring(0, 12000);

// 4) Langue lisible pour le prompt.
const LANGS = { fr: 'français', en: 'English', es: 'español' };
const langLabel = LANGS[lang] || 'français';

const prompt = `Tu es responsable marketing chez NeuraWeb (agence web + IA / automatisation pour PME).\n` +
`À partir de l'article ci-dessous, crée des publications pour Facebook et LinkedIn.\n` +
`IMPORTANT : rédige TOUT le contenu en ${langLabel} (la langue de l'article).\n\n` +
`=== ARTICLE ===\nTitre : ${title}\nRésumé : ${excerpt}\nContenu :\n${content}\n=== FIN ===\n\n` +
`Règles Facebook : 120-180 mots, ton professionnel et accessible aux PME, un CTA clair, maximum 4 hashtags.\n` +
`Règles LinkedIn : 300-500 mots, ton expert, structure aérée, une question d'ouverture, un CTA final.\n` +
`Le champ "hook" est une première phrase d'accroche courte et percutante.\n\n` +
`Réponds avec un JSON STRICTEMENT conforme à ce schéma :\n` +
`{"facebook":{"hook":"","post":""},"linkedin":{"hook":"","post":""}}`;

return [{ json: { slug, lang, path, commit, title, seoTitle, excerpt, image, prompt } }];

// Extrait et parse le JSON renvoyé par Gemini, puis fusionne avec les champs article.
const src = $('Parse & Validate').first().json;

let text = $json.candidates?.[0]?.content?.parts?.[0]?.text;
if (!text) throw new Error('Réponse Gemini vide: ' + JSON.stringify($json).slice(0, 500));

// Sécurité : retire d'éventuels fences ```json ... ``` malgré responseMimeType.
text = text.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();

let social;
try {
  social = JSON.parse(text);
} catch (e) {
  throw new Error('JSON Gemini invalide: ' + text.slice(0, 500));
}

const fb = social.facebook || {};
const li = social.linkedin || {};

return [{
  json: {
    slug: src.slug,
    lang: src.lang,
    title: src.title,
    image: src.image,
    facebook_hook: fb.hook || '',
    facebook_post: fb.post || '',
    linkedin_hook: li.hook || '',
    linkedin_post: li.post || '',
    status: 'pending',
    source_path: src.path,
    source_commit: src.commit
  }
}];
